class EventManager {
/** Subject: keeps a list of observers for every event type. */
constructor() {
this._subscribers = new Map();
}
subscribe(event, observer) {
if (!this._subscribers.has(event)) this._subscribers.set(event, []);
this._subscribers.get(event).push(observer);
}
unsubscribe(event, observer) {
const list = this._subscribers.get(event);
list.splice(list.indexOf(observer), 1);
}
publish(event, data) {
const observers = this._subscribers.get(event) || [];
console.log(`Event published: ${event} (${observers.length} subscriber(s))`);
for (const observer of observers) observer.update(event, data);
}
}
